import attr
from typing import Optional

from .connection_details import SshServiceDetails, TelnetConnectionDetails
from .gnb.networkaddress import NetworkAddress


@attr.s(cmp=False)
class RNC(object):
    """
    3G RNC class

    :param int rnc_id: RNC ID (i.e. RNC-31 would have ID 31)
    :param NetworkAddress oms_ip: IP address of RNC OMS service
    :param Optional[SshServiceDetails] logging_ssh_connection_details: ssh service details that
                                       can be used for logging into RNC
    :param Optional[TelnetConnectionDetails] logging_telnet_connection_details: telnet connection
                                             details that can be used for logging into RNC
    """
    rnc_id = attr.ib(type=int)
    oms_ip = attr.ib(type=NetworkAddress)
    logging_ssh_connection_details = attr.ib(default=None, type=Optional[SshServiceDetails])
    logging_telnet_connection_details = attr.ib(default=None, type=Optional[TelnetConnectionDetails])


@attr.s(cmp=False)
class BSC(object):
    """
    2G BSC class

    :param str name: BSC name (i.e. BSC_Leopard, mcBSC_31)
    :param Optional[SshServiceDetails] logging_ssh_connection_details: ssh service details
                                        that can be used for logging into BSC
    :param Optional[TelnetConnectionDetails] logging_telnet_connection_details: telnet connection
                                            details that can be used for logging into BSC
    """
    name = attr.ib(type=str)
    logging_ssh_connection_details = attr.ib(default=None, type=Optional[SshServiceDetails])
    logging_telnet_connection_details = attr.ib(default=None, type=Optional[TelnetConnectionDetails])
